  },
  Activity_116818_ActivityPlot = {
    Text = "The Stars are Its eyes, not merely watching, but monitoring everything in existence.\nYou believe you have escaped Its gaze, yet the truth is—you remain trapped within Its dream.\n\"Caught... you...\"\nAs They seized you, the Stars let out a low, satisfied sigh."
