  },
  Activity_25012_ActivityPlot = {
    Text = "Ladies and gentlemen.\nThe gentle night has drawn back its curtain—prepare your finest drink.\nThis is a long story. Allow us to tell it at our leisure."
  },
  Activity_25012_ActivityTips = {
    Text = [[
<Title:Participation Conditions>
Complete "Investigation Operation" 2-9 (Normal) to participate.
